{
  "projects": [],
  "intention": "Investigate whether unfamiliar tubers can be evaluated without risking poisoning, while keeping known-safe roots for survival.",
  "steps": [
    {
      "action": {
        "interface": "request",
        "args": {
          "name": "Non-ingestive food usefulness and hazard assessment",
          "function": "Determine what physically supported, non-ingestive tests could establish nutritional usefulness or detect hazards in my actual tuber sample. Distinguish measured results from unresolved hazards; do not treat a negative limited test as universal safety.",
          "conditions": "At tick 330 I hold a tuber sample gathered from forest-tuber-0 and a retained opened portion item-329-sol-2041. Paid internal examination found little observable deterioration but explicitly did not establish nutrition, digestibility or toxin absence. Root and berry are personally known safe foods. Existing relative drying measurements do not establish chemical safety.",
          "inputs": "Actual retained tuber portions; any additional reference materials or apparatus must first be identified and physically obtained. Suitable methods and dependencies are unknown.",
          "costs": "Unknown; specify real material, energy, time and reference requirements before testing. Do not require tasting an unknown sample.",
          "effects": "Provide a feasible evidence-limited testing pathway, or explain the missing independently verifiable prerequisites if no such assessment is currently implementable. No automatic edibility certificate, detoxification or nutrition discovery."
        }
      },
      "repeat": 1,
      "until": null,
      "guard": {
        "path": "self.satiety",
        "comparison": "gt",
        "value": 40
      }
    }
  ],
  "repeat": 1,
  "until": null,
  "interrupts": [
    "requested",
    "review-rejected",
    "failed",
    "injured",
    "local-hazard"
  ],
  "notes": [
    "At tick 330 health is 100, satiety 67, and five known-safe roots remain in inventory.",
    "The opened tuber showed little observable deterioration; nutrition and toxicity remain unknown."
  ],
  "preferences": [
    "Retain known-safe provisions while investigating unfamiliar food.",
    "Avoid ingestion as a test of unknown toxicity."
  ]
}
